NEW_FILES = {'tests/test_asphalt_albedo.py': '"""Delco\'s asphalt mints at a weathered road\'s albedo (0.66.0).\n\nThe base colours were minted at #33322f / #3a3936 / #2c2b28 and the pack\'s albedo map measured 0.035 linear -- darker\nthan fresh asphalt (about 0.05-0.10) and a third of a weathered road\'s (0.10-0.20). At Blue Hour the vertical slice\'s\navenue read as a black band under every street view (the factory\'s `docs/findings/sodium_pools/`). The map is minted\nhere as the theme library mints it and its mean is held to an old road\'s band.\n\nFAILS ON 0.65.0: 0.035.\n"""\nimport os\nimport subprocess\nimport sys\n\nimport numpy as np\nimport pytest\nfrom PIL import Image\n\nROOT = os.path.normpath(os.path.join(os.path.dirname(__file__), ".."))\n\n\n# asphalt_street, an older grammar no Delco theme draws, is left as it was: nothing has seen it on a level.\n@pytest.mark.parametrize("grammar", ["asphalt_delco"])\ndef test_the_asphalt_is_a_weathered_roads_albedo(grammar, tmp_path):\n    out = tmp_path / grammar\n    r = subprocess.run([sys.executable, "-m", "pixelcoat.cli.main", "proc-pack",\n                        os.path.join(ROOT, "profiles", "materials", grammar + ".json"),\n                        "--out", str(out), "--asset-id", grammar, "--size", "256"],\n                       cwd=ROOT, capture_output=True, text=True)\n    assert r.returncode == 0, r.stdout + r.stderr\n    a = np.asarray(Image.open(out / (grammar + "_albedo.png")).convert("RGB"), dtype=float) / 255.0\n    linear = float((a ** 2.2).mean())\n    assert 0.08 <= linear <= 0.20, linear\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
